namespace ScopeMaker {
public class BackgroundEntry {public string Key,Mode,File,Thumbnail,Source,Sha256;public int Scene,Width,Height;}
public class BackgroundChoice {public string Key="",File="";public int Dim;public bool Grid=true;}
public static class BackgroundLibrary {
 public static string DirectoryPath {get{return Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"assets","backgrounds");}}
 public static List<BackgroundEntry> Entries(){string path=Path.Combine(DirectoryPath,"manifest.json");return System.IO.File.Exists(path)?new JavaScriptSerializer().Deserialize<List<BackgroundEntry>>(System.IO.File.ReadAllText(path)):new List<BackgroundEntry>();}
 public static string Resolve(string key){var entry=Entries().FirstOrDefault(e=>e.Key==key);if(entry==null)throw new FileNotFoundException(L.T("Фон WT не найден. Папка assets должна находиться рядом с программой."));string path=Path.GetFullPath(Path.Combine(DirectoryPath,entry.File));if(!path.StartsWith(Path.GetFullPath(DirectoryPath)+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new FormatException(L.T("Недопустимый путь фона"));return path;}
 public static Bitmap Load(string path){using(var image=Image.FromFile(path))return new Bitmap(image);}
 public static void Tests(List<string> results){var entries=Entries();if(entries.Count!=16||entries.Select(e=>e.Key).Distinct().Count()!=16)throw new Exception("Expected 16 distinct WT backgrounds");foreach(var entry in entries){using(var img=Image.FromFile(Resolve(entry.Key))){if(img.Width!=entry.Width||img.Height!=entry.Height||img.Width!=3840||img.Height!=2160)throw new Exception("Background resolution changed: "+entry.Key);}using(var thumb=Image.FromFile(Path.Combine(DirectoryPath,entry.Thumbnail))){if(thumb.Width<1||thumb.Height<1)throw new Exception("Invalid thumbnail");}}
  results.Add("PASS: All 16 native 3840x2160 WT backgrounds and thumbnails load");
  var p=MainWindow.Preset(0);string before=Blk.Export(p);p.BackgroundKey="3_nightvision";p.BackgroundDim=20;p.PreviewGrid=false;string json=new JavaScriptSerializer().Serialize(p);var restored=new JavaScriptSerializer().Deserialize<Project>(json);if(restored.BackgroundKey!=p.BackgroundKey||restored.BackgroundDim!=20||restored.PreviewGrid)throw new Exception("Background settings not persisted");results.Add("PASS: Project persistence retains background, mode, dimming and grid state");if(Blk.Export(p)!=before)throw new Exception("Background leaked into sight export");results.Add("PASS: Background settings do not alter exported BLK geometry");
  MainWindow.BackgroundChecks(results);BackgroundDialog.CheckDialog(results);
 }
}
public class BackgroundPreview : Control {
 public Image Picture;public int Dim;
 public BackgroundPreview(){DoubleBuffered=true;ResizeRedraw=true;BackColor=Color.FromArgb(17,23,30);}
 protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);if(Picture==null){TextRenderer.DrawText(e.Graphics,L.T("Фон не выбран"),Font,ClientRectangle,Color.Gray,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter);return;}float ratio=Math.Min((float)Width/Picture.Width,(float)Height/Picture.Height),w=Picture.Width*ratio,h=Picture.Height*ratio;var rect=new RectangleF((Width-w)/2,(Height-h)/2,w,h);e.Graphics.DrawImage(Picture,rect);if(Dim>0)using(var shade=new SolidBrush(Color.FromArgb(Dim*255/100,0,0,0)))e.Graphics.FillRectangle(shade,rect);}
}
public class BackgroundDialog : Form {
 List<BackgroundEntry> entries;List<PictureBox> thumbnails=new List<PictureBox>();List<Panel> cards=new List<Panel>();ComboBox mode=new ModernCombo();TrackBar dim=new TrackBar();CheckBox grid=new CheckBox();Label dimLabel=new Label(),details=new Label();BackgroundPreview preview=new BackgroundPreview();string selectedKey="",selectedFile="";int scene=1;Image picture;bool starting=true;
 readonly string[] modes={"day","night","nightvision","thermal"};
 public BackgroundChoice Choice;
 public BackgroundDialog(Project project){
  Text=L.T("Фоны редактора War Thunder");Size=new Size(1060,840);MinimumSize=new Size(960,780);StartPosition=FormStartPosition.CenterParent;BackColor=Color.FromArgb(27,35,46);ForeColor=Color.FromArgb(220,229,239);Font=new Font("Segoe UI",10);entries=BackgroundLibrary.Entries();selectedKey=project.BackgroundKey??"";selectedFile=project.BackgroundFile??"";var current=entries.FirstOrDefault(e=>e.Key==selectedKey);if(current!=null)scene=current.Scene;
  var layout=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(16),ColumnCount=1,RowCount=6};layout.RowStyles.Add(new RowStyle(SizeType.Absolute,32));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,42));layout.RowStyles.Add(new RowStyle(SizeType.Percent,100));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,142));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,60));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,44));Controls.Add(layout);
  layout.Controls.Add(new Label{Text=L.T("4 СЦЕНЫ · ДЕНЬ / НОЧЬ / ПНВ / ТЕПЛОВИЗОР"),ForeColor=Color.FromArgb(92,245,156),AutoSize=true},0,0);
  var toolbar=new FlowLayoutPanel{Dock=DockStyle.Fill};layout.Controls.Add(toolbar,0,1);toolbar.Controls.Add(new Label{Text=L.T("Режим"),AutoSize=true,Padding=new Padding(0,5,8,0)});mode.Width=180;mode.DropDownStyle=ComboBoxStyle.DropDownList;mode.ForeColor=Color.Black;mode.Items.AddRange(new object[]{L.T("День"),L.T("Ночь"),L.T("ПНВ"),L.T("Тепловизор")});mode.SelectedIndex=current==null?0:Array.IndexOf(modes,current.Mode);toolbar.Controls.Add(mode);AddButton(toolbar,L.T("Свой файл…"),OwnFile);AddButton(toolbar,L.T("Без фона"),delegate{selectedKey="";selectedFile="";RefreshPreview();});
  preview.Dock=DockStyle.Fill;layout.Controls.Add(preview,0,2);
  var strip=new FlowLayoutPanel{Dock=DockStyle.Fill,WrapContents=false,AutoScroll=true,Padding=new Padding(0,8,0,0)};layout.Controls.Add(strip,0,3);
  for(int i=1;i<=4;i++){int number=i;var card=new Panel{Width=205,Height=125,Padding=new Padding(3),Margin=new Padding(0,0,10,0),BackColor=BackColor,Cursor=Cursors.Hand};var thumb=new PictureBox{Dock=DockStyle.Top,Height=100,SizeMode=PictureBoxSizeMode.Zoom,BackColor=Color.FromArgb(17,23,30)};var label=new Label{Text=L.T("Сцена ")+i,Dock=DockStyle.Bottom,Height=20,TextAlign=ContentAlignment.MiddleCenter};card.Controls.Add(thumb);card.Controls.Add(label);EventHandler choose=delegate{scene=number;selectedFile="";selectedKey=number+"_"+modes[mode.SelectedIndex];RefreshPreview();};card.Click+=choose;thumb.Click+=choose;label.Click+=choose;cards.Add(card);thumbnails.Add(thumb);strip.Controls.Add(card);}
  var controls=new FlowLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(0,7,0,0)};layout.Controls.Add(controls,0,4);dimLabel.Size=new Size(150,25);controls.Controls.Add(dimLabel);dim.Minimum=0;dim.Maximum=70;dim.TickFrequency=10;dim.Width=245;dim.Value=Math.Max(0,Math.Min(70,project.BackgroundDim));controls.Controls.Add(dim);grid.Text=L.T("Сетка редактора");grid.Checked=project.PreviewGrid;grid.AutoSize=true;controls.Controls.Add(grid);
  var bottom=new FlowLayoutPanel{Dock=DockStyle.Fill};layout.Controls.Add(bottom,0,5);details.Size=new Size(620,35);bottom.Controls.Add(details);AddButton(bottom,L.T("Применить"),delegate{Choice=new BackgroundChoice{Key=selectedKey,File=selectedFile,Dim=dim.Value,Grid=grid.Checked};DialogResult=DialogResult.OK;});var cancel=new ModernButton{Text=L.T("Отмена"),DialogResult=DialogResult.Cancel,AutoSize=true,Height=34};bottom.Controls.Add(cancel);CancelButton=cancel;
  mode.SelectedIndexChanged+=delegate{if(starting||L.Applying)return;selectedFile="";selectedKey=scene+"_"+modes[mode.SelectedIndex];RefreshThumbnails();RefreshPreview();};dim.ValueChanged+=delegate{dimLabel.Text=L.T("Затемнение: ")+dim.Value+"%";preview.Dim=dim.Value;preview.Invalidate();};starting=false;Ui.Theme(this);RefreshThumbnails();RefreshPreview();dimLabel.Text=L.T("Затемнение: ")+dim.Value+"%";preview.Dim=dim.Value;
 }
 void AddButton(Control host,string caption,Action action){var button=new ModernButton{Text=caption,AutoSize=true,Height=34,Primary=caption==L.T("Применить"),Margin=new Padding(5,0,5,0)};button.Click+=delegate{try{action();}catch(Exception ex){MessageBox.Show(this,ex.Message,L.T("Фон"),MessageBoxButtons.OK,MessageBoxIcon.Warning);}};host.Controls.Add(button);}
 void RefreshThumbnails(){for(int i=0;i<4;i++){if(thumbnails[i].Image!=null)thumbnails[i].Image.Dispose();var entry=entries.FirstOrDefault(e=>e.Scene==i+1&&e.Mode==modes[mode.SelectedIndex]);thumbnails[i].Image=entry==null?null:BackgroundLibrary.Load(Path.Combine(BackgroundLibrary.DirectoryPath,entry.Thumbnail));}}
 void RefreshPreview(){Image next=null;string message=L.T("Без фона");try{if(!String.IsNullOrEmpty(selectedFile)){next=BackgroundLibrary.Load(selectedFile);message=Path.GetFileName(selectedFile);}else if(!String.IsNullOrEmpty(selectedKey)){next=BackgroundLibrary.Load(BackgroundLibrary.Resolve(selectedKey));message=L.T("Сцена ")+scene+" · "+mode.SelectedItem+" · "+next.Width+"×"+next.Height;}}catch(Exception ex){message=ex.Message;selectedKey="";selectedFile="";}preview.Picture=next;if(picture!=null)picture.Dispose();picture=next;preview.Invalidate();details.Text=message;for(int i=0;i<cards.Count;i++){bool selected=selectedKey==(i+1)+"_"+modes[mode.SelectedIndex];cards[i].BackColor=selected?Ui.Accent:BackColor;foreach(var label in cards[i].Controls.OfType<Label>())label.ForeColor=selected?Color.White:Ui.Ink;}}
 void OwnFile(){using(var d=new OpenFileDialog{Filter=L.T("Изображения|*.png;*.jpg;*.jpeg;*.bmp")})if(d.ShowDialog(this)==DialogResult.OK){using(var check=Image.FromFile(d.FileName)){}selectedFile=d.FileName;selectedKey="";RefreshPreview();}}
 public void Screenshot(string path){Show();Application.DoEvents();using(var bmp=new Bitmap(Width,Height)){DrawToBitmap(bmp,new Rectangle(0,0,Width,Height));bmp.Save(path);}Close();}
 public static void CheckDialog(List<string> results){using(var d=new BackgroundDialog(new Project{BackgroundKey="1_day"})){d.Show();Application.DoEvents();if(d.preview.Width<600||d.preview.Height<250||d.picture==null)throw new Exception("Background gallery preview is not visible");d.mode.SelectedIndex=3;if(d.selectedKey!="1_thermal"||d.picture==null)throw new Exception("Gallery mode switch failed");results.Add("PASS: Gallery displays a full-size preview and switches day to thermal");d.Close();}}
 protected override void Dispose(bool disposing){if(disposing){preview.Picture=null;if(picture!=null)picture.Dispose();foreach(var thumb in thumbnails)if(thumb.Image!=null)thumb.Image.Dispose();}base.Dispose(disposing);}
}
public partial class MainWindow {
 string loadedBackgroundKey,loadedBackgroundFile,backgroundIssue="";
 void RestoreBackground(){string key=Doc.BackgroundKey??"",file=Doc.BackgroundFile??"";if(key==loadedBackgroundKey&&file==loadedBackgroundFile)return;Image next=null;backgroundIssue="";try{if(file.Length>0)next=BackgroundLibrary.Load(file);else if(key.Length>0)next=BackgroundLibrary.Load(BackgroundLibrary.Resolve(key));}catch(Exception ex){backgroundIssue=L.T("Не удалось загрузить фон: ")+ex.Message;}if(background!=null)background.Dispose();background=next;loadedBackgroundKey=key;loadedBackgroundFile=file;canvas.Invalidate();}
 void ChooseBackground(){using(var d=new BackgroundDialog(Doc))if(d.ShowDialog(this)==DialogResult.OK){ApplyBackground(d.Choice);}}
 void ApplyBackground(BackgroundChoice choice){if(Doc.BackgroundKey==choice.Key&&Doc.BackgroundFile==choice.File&&Doc.BackgroundDim==choice.Dim&&Doc.PreviewGrid==choice.Grid)return;Remember();Doc.BackgroundKey=choice.Key;Doc.BackgroundFile=choice.File;Doc.BackgroundDim=choice.Dim;Doc.PreviewGrid=choice.Grid;RestoreBackground();Changed();if(backgroundIssue.Length>0)Status(backgroundIssue);}
 public static void BackgroundChecks(List<string> results){using(var w=new MainWindow()){w.ApplyBackground(new BackgroundChoice{Key="1_day",Grid=false});if(w.background==null||w.background.Width!=3840)throw new Exception("Main canvas failed to load background");w.Undo(false);if(w.background!=null||w.Doc.BackgroundKey!="")throw new Exception("Background undo failed");w.Undo(true);if(w.background==null||w.Doc.BackgroundKey!="1_day")throw new Exception("Background redo failed");results.Add("PASS: Background selection loads on canvas and supports undo/redo");w.ApplyBackground(new BackgroundChoice{Key="3_thermal"});if(w.background==null||w.Doc.BackgroundKey!="3_thermal")throw new Exception("Background mode switch failed");w.ApplyBackground(new BackgroundChoice());if(w.background!=null)throw new Exception("Removing background did not release it");results.Add("PASS: Background mode switching and no-background selection work");w.dirty=false;}}
 public void BackgroundScreenshot(string path){Doc=Blk.Import(File.ReadAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"templates","game","all_tanks__us_modern_sight_with_range.blk")));Doc.Title=L.T("Современный прицел · США");ApplyBackground(new BackgroundChoice{Key="1_day",Grid=false});RefreshLayers(0);UpdateProps();Screenshot(path);}
}
}
